arguments.command:
cd /workspace && python3 - <<'PY'
from pathlib import Path
p=Path('src/utils/mem_init.h');s=p.read_text()
s=s.replace('#include <fstream>\n#include <iomanip>\n','#include <fstream>\n#include <iomanip>\n#include <vector>\n')
s=s.replace('''    // Node processing queue
    ScampTrieNode* node_queue[1<<22];
    uint32_t node_queue_head, node_queue_tail;

    // BRAM Node data (multiple stages)
    std::bitset<256> ram[RAM_NUM][(10 * MEGA_BYTES) / 256]; // default 10MB / Stage
    uint32_t ram_len[RAM_NUM];

    // BRAM Nexthop Array data
    nexthop_t nexthop_array[200001];
    uint32_t nexthop_array_size;
''','''    // Node processing queue (heap-backed so a MemInit object is small enough
    // to be constructed on the normal 8 MiB process stack).
    std::vector<ScampTrieNode*> node_queue;
    uint32_t node_queue_head, node_queue_tail;

    // BRAM Node data (multiple stages)
    std::vector<std::bitset<256>> ram[RAM_NUM];
    uint32_t ram_len[RAM_NUM];

    // BRAM Nexthop Array data
    std::vector<nexthop_t> nexthop_array;
    uint32_t nexthop_array_size;
''')
p.write_text(s)
p=Path('src/utils/mem_init.cpp');s=p.read_text()
s=s.replace('''MemInit::MemInit(ScampTrieDynamic* value) : trie(value) {
    memset(ram,0,sizeof(ram));memset(ram_len,0,sizeof(ram_len));
    node_queue_head=node_queue_tail=0;nexthop_array_size=0;
}
''','''MemInit::MemInit(ScampTrieDynamic* value) : trie(value) {
    memset(ram_len,0,sizeof(ram_len));
    node_queue.resize(1u << 22);
    nexthop_array.resize(200001);
    for (int s = 0; s < RAM_NUM; ++s)
        ram[s].resize((10 * MEGA_BYTES) / 256);
    node_queue_head=node_queue_tail=0;nexthop_array_size=0;
}
''')
p.write_text(s)
PY
python3 build.py && /tmp/direct_bin 2>/dev/null; true
# Rebuild direct test with updated src
rm -rf /tmp/direct_src && cp -a src /tmp/direct_src && cat > /tmp/direct_src/main.cpp <<'EOF'
#include "scamptrie_dynamic.h"
#include "utils/mem_init.h"
#include "image.hpp"
#include <iostream>
int main(){
    ScampTrieDynamic live;
    live.set_insert_prefix_timing_enabled(false);
    live.insert_prefix(ip6_t{0,0},0,123);
    live.insert_prefix(ip6_t{0x20010db800000001ULL,0x0000000000000001ULL},128,456);
    uint32_t marker=0;
    std::cout << live.lookup(ip6_t{0,0},marker) << " "
              << live.lookup(ip6_t{0x20010db800000001ULL,0x0000000000000002ULL},marker) << "\n";
    MemInit exporter(&live);
    ImageData image=exporter.capture();
    MemoryImage loaded;
    std::cout << loaded.load(image) << " " << loaded.lookup(ip6_t{0,0}) << " "
              << loaded.lookup(ip6_t{0x20010db800000001ULL,0x0000000000000002ULL}) << "\n";
    return 0;
}
EOF
python3 build.py --source /tmp/direct_src --output /tmp/direct_bin >/dev/null && /tmp/direct_bin
